import React, { useState } from "react";

export default function SafetyCheck() {
  const [latitude, setLatitude] = useState("");
  const [longitude, setLongitude] = useState("");
  const [result, setResult] = useState("");

  const handleCheckSafety = async () => {
    try {
      const response = await fetch("http://localhost:5000/api/safety/check", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          latitude: parseFloat(latitude),
          longitude: parseFloat(longitude),
        }),
      });

      if (!response.ok) {
        throw new Error("Network response was not ok");
      }

      const data = await response.json();
      setResult(data.message);
    } catch (error) {
      console.error("Error checking safety:", error);
      setResult("Error checking safety");
    }
  };

  return (
    <div style={{ textAlign: "center", marginTop: "50px" }}>
      <h2>Smart Tourist Safety Check</h2>
      <input
        type="number"
        placeholder="Enter Latitude"
        value={latitude}
        onChange={(e) => setLatitude(e.target.value)}
      />
      <input
        type="number"
        placeholder="Enter Longitude"
        value={longitude}
        onChange={(e) => setLongitude(e.target.value)}
      />
      <button onClick={handleCheckSafety}>Check Safety</button>

      {result && (
        <p style={{ marginTop: "20px", fontWeight: "bold" }}>{result}</p>
      )}
    </div>
  );
}
